scope.code:
job.caseData = structuredClone(retainedCase);
job.caseData.parameters = { ...job.caseData.parameters, ...parameters };
job.caseData.tables.arrangements = arrangements;
job.caseData.tables.slotConfirmations = slotConfirmations;

run.code:
const solved = await invokeCLI(['workflow', 'solve', '--run', preparedFile,
  '--created-at', createdAt, '--timeout-ms', String(options.timeoutMs ?? 30000),
  '--output', path.join(directory, 'review.json')], transcript);

completion.code:
if (solved.exitCode !== CLI_EXIT_CODE.COMPLETED) {
  row.status = BATCH_STATUS.UNAVAILABLE;
  row.diagnostics.push(...diagnostics(solved, 'WORKFLOW_UNAVAILABLE'));
}
const retainedWorkflow = await optionalJSON(path.join(directory, 'review.json'));

retention.code:
assert(run.execution?.status === EXECUTION_STATUS.COMPLETED, `The assessment did not complete (${text(run.execution?.status) || 'unknown execution status'}).`);
const report = run.report;
assert(report?.format === 'decision-lab-report/1', 'The run has no complete retained report.');
const completeness = report.completeness;
assert(inspectReportCompleteness(report).complete, 'The retained report is incomplete or truncated.');
